#include <bits/stdc++.h>
using namespace std;

vector<int> countingSort(vector<int>& arr) {
    if (arr.empty()) return {};

    int maxVal = *max_element(arr.begin(), arr.end());
    vector<int> count(maxVal + 1, 0);

    // Phase 1: Count each value
    for (int num : arr) {
        count[num]++;
    }

    // Phase 2: Reconstruct sorted output
    vector<int> output;
    for (int val = 0; val <= maxVal; val++) {
        while (count[val]--) {
            output.push_back(val);
        }
    }

    return output;
}

int main() {
    vector<int> arr = {4, 2, 2, 8, 3, 3, 1};

    vector<int> sorted = countingSort(arr);

    for (int num : sorted) {
        cout << num << " ";
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

vector<int> countingSortStable(vector<int>& arr, int maxVal) {
    vector<int> count(maxVal + 1, 0);
    vector<int> output(arr.size());

    // Step 1: Count frequency
    for (int num : arr) {
        count[num]++;
    }

    // Step 2: Cumulative count
    // count[i] = number of elements <= i
    for (int i = 1; i < count.size(); i++) {
        count[i] += count[i - 1];
    }

    // Step 3: Place elements from right to left (stability)
    for (int i = arr.size() - 1; i >= 0; i--) {
        int num = arr[i];
        output[count[num] - 1] = num;
        count[num]--;
    }

    return output;
}

int main() {
    vector<int> arr = {4, 2, 2, 8, 3, 3, 1};

    vector<int> sorted = countingSortStable(arr, 8);

    for (int num : sorted) {
        cout << num << " ";
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

vector<int> countingSortByDigit(vector<int>& arr, int place) {
    vector<int> count(10, 0);
    vector<int> output(arr.size());

    // Step 1: Count occurrences of each digit
    for (int num : arr) {
        int digit = (num / place) % 10;
        count[digit]++;
    }

    // Step 2: Prefix sum
    for (int i = 1; i < 10; i++) {
        count[i] += count[i - 1];
    }

    // Step 3: Place elements from right to left (stable)
    for (int i = arr.size() - 1; i >= 0; i--) {
        int digit = (arr[i] / place) % 10;
        output[count[digit] - 1] = arr[i];
        count[digit]--;
    }

    return output;
}

vector<int> radixSort(vector<int>& arr) {
    if (arr.empty()) return arr;

    int maxVal = *max_element(arr.begin(), arr.end());

    int place = 1;
    while (maxVal / place > 0) {     // Process each digit position
        arr = countingSortByDigit(arr, place);
        place *= 10;
    }

    return arr;
}

int main() {
    vector<int> arr = {170, 45, 75, 90, 802, 24, 2, 66};

    vector<int> sorted = radixSort(arr);

    for (int num : sorted) {
        cout << num << " ";
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

vector<double> bucketSort(vector<double>& arr, int numBuckets = 10) {
    if (arr.empty()) return {};

    double minVal = *min_element(arr.begin(), arr.end());
    double maxVal = *max_element(arr.begin(), arr.end());

    double bucketRange = (maxVal - minVal) / numBuckets;

    // Edge case: all elements are the same
    if (bucketRange == 0) return arr;

    // Step 1: Create empty buckets
    vector<vector<double>> buckets(numBuckets);

    // Step 2: Distribute elements into buckets
    for (double num : arr) {
        int idx = (num - minVal) / bucketRange;

        if (idx == numBuckets) idx--; // Handle max value edge case

        buckets[idx].push_back(num);
    }

    // Step 3: Sort each bucket and concatenate
    vector<double> result;

    for (auto& bucket : buckets) {
        sort(bucket.begin(), bucket.end()); // sort individual bucket

        for (double num : bucket) {
            result.push_back(num);
        }
    }

    return result;
}

int main() {
    vector<double> arr = {
        0.78, 0.17, 0.39, 0.26,
        0.72, 0.94, 0.21, 0.12, 0.23, 0.68
    };

    vector<double> sorted = bucketSort(arr);

    for (double num : sorted) {
        cout << num << " ";
    }

    return 0;
}
